void tr_zcl_endpoint_config_init(void)
{
    zb_ieee_addr_t tmpAddr = { 0 };
    zb_ieee_addr_t ieeeAddr = { 0 };

    // check user override callback for eui64
    if(tr_eui64_user_override_cb(tmpAddr))
    {
        // adjust to correct endian-ness
        for ( zb_uint8_t i = 0 ; i < 8 ; i++ )
        {
            ieeeAddr[i] = tmpAddr[7-i];
        }
    }
    else
    {
        // check MFG token
        if(!tr_mfg_token_check_erased(TR_MFG_TOKEN_CUSTOM_EUI))
        {
            tr_get_mfg_token(tmpAddr, TR_MFG_TOKEN_CUSTOM_EUI);

            // adjust to correct endian-ness
            for ( zb_uint8_t i = 0 ; i < 8 ; i++ )
            {
                ieeeAddr[i] = tmpAddr[7-i];
            }
        }
        // get internal eui64
        else
        {
            tr_zb_osif_get_eui64(ieeeAddr);
        }
    }

    tr_app_printf("\nEUI64: ");

    for ( zb_uint8_t i = 8 ; i != 0 ; i-- )
    {
        tr_app_printf("%02X ", ieeeAddr[i - 1]);
    }
    tr_app_printf("\n");

    /* Set up defaults for the commissioning */
    zb_set_long_address(ieeeAddr);

#ifdef ZB_ED_ROLE
    zb_set_network_ed_role(0);
#elif defined ZB_ROUTER_ROLE
    zb_set_network_router_role(0);
#elif defined ZB_COORDINATOR_ROLE
    zb_set_network_coordinator_role(0);
#endif

    zb_set_nvram_erase_at_start(ZB_FALSE);

    /* Register application callback for reading application data from NVRAM */
    zb_nvram_register_app4_read_cb(tr_nvram_read_app_data_cb);
    /* Register application callback for writing application data to NVRAM */
    zb_nvram_register_app4_write_cb(tr_nvram_write_app_data_cb, tr_get_nvram_data_size);

    /* Set MFG ID */
    if(!tr_mfg_token_check_erased(TR_MFG_TOKEN_MANUF_ID))
    {
        tr_mfg_tok_type_manuf_id mfg_id;
        tr_get_mfg_token(&mfg_id, TR_MFG_TOKEN_MANUF_ID);
        tr_app_printf("Setting MFG ID from Token: 0x%04X\n", mfg_id.value);
        zdo_set_node_descriptor_manufacturer_code(mfg_id.value);
    }
    else
    {
        zdo_set_node_descriptor_manufacturer_code(TR_DEVICE_MANUFACTURER_ID);
    }

    /* Register device ZCL context */
    ZB_AF_REGISTER_DEVICE_CTX(&tr_device_ctx);

    /* Register cluster commands handler for specific endpoint(s) */
    ZB_AF_SET_ENDPOINT_HANDLER(TR_DEVICE_EP1, tr_zcl_specific_cluster_cmd_handler);
    ZB_MEMSET(&g_device_attr_context_ep1, 0, sizeof(device_attr_context_ep1_t));
    tr_zcl_endpoint_config_attr_init(TR_DEVICE_EP1);

    tr_zcl_endpoint_config_reporting_init();
}

