void tr_zcl_endpoint_config_reporting_init(void)
{
    zb_zcl_reporting_info_t rep_info;
    ZB_MEMSET(&rep_info, 0, sizeof(zb_zcl_reporting_info_t));

    tr_attr_report_config_t default_config[] = TR_DEVICE_REPORTING_CONFIG_DEFAULTS;

    for ( zb_uint8_t i = 0 ; i < TR_DEVICE_NUM_DEFAULT_REPORTABLE_ATTRS ; i++ )
    {
        rep_info.direction      = default_config[i].direction;
        rep_info.ep             = default_config[i].endpoint;
        rep_info.cluster_id     = default_config[i].cluster_id;
        rep_info.cluster_role   = default_config[i].cluster_role;
        rep_info.attr_id        = default_config[i].attr_id;
        rep_info.dst.profile_id = default_config[i].profile_id;
        rep_info.manuf_code     = default_config[i].manuf_code;

        rep_info.u.send_info.min_interval     = default_config[i].min_interval;
        rep_info.u.send_info.max_interval     = default_config[i].max_interval;
        rep_info.u.send_info.def_min_interval = default_config[i].min_interval;
        rep_info.u.send_info.def_max_interval = default_config[i].max_interval;

        switch (default_config[i].data_type)
        {
            case TR_ZCL_DATA8_ATTR_TYPE:
            case TR_ZCL_BOOLEAN_ATTR_TYPE:
            case TR_ZCL_BITMAP8_ATTR_TYPE:
            case TR_ZCL_INT8U_ATTR_TYPE:
            case TR_ZCL_ENUM8_ATTR_TYPE:
                rep_info.u.send_info.delta.u8 = (zb_uint8_t)default_config[i].reportable_change;
                break;

            case TR_ZCL_INT8S_ATTR_TYPE:
                rep_info.u.send_info.delta.s8 = (zb_int8_t)default_config[i].reportable_change;
                break;

            case TR_ZCL_DATA16_ATTR_TYPE:
            case TR_ZCL_BITMAP16_ATTR_TYPE:
            case TR_ZCL_INT16U_ATTR_TYPE:
            case TR_ZCL_ENUM16_ATTR_TYPE:
                rep_info.u.send_info.delta.u16 = (zb_uint16_t)default_config[i].reportable_change;
                break;

            case TR_ZCL_INT16S_ATTR_TYPE:
                rep_info.u.send_info.delta.s16 = (zb_int16_t)default_config[i].reportable_change;
                break;

            case TR_ZCL_DATA32_ATTR_TYPE:
            case TR_ZCL_BITMAP32_ATTR_TYPE:
            case TR_ZCL_INT32U_ATTR_TYPE:
                rep_info.u.send_info.delta.u32 = (zb_uint32_t)default_config[i].reportable_change;
                break;

            case TR_ZCL_INT32S_ATTR_TYPE:
                rep_info.u.send_info.delta.s32 = (zb_int32_t)default_config[i].reportable_change;
                break;

            default:
                break;
        }
        zb_zcl_put_reporting_info(&rep_info, ZB_TRUE);
    }
}
